/// Side of the code itself, in video pixels (the same on the matrix and end scenes).
pub const QR_SIZE: f32 = 500.0;
/// The white tile behind the code.
pub const TILE: f32 = QR_SIZE + 60.0;
/// Center of the tile on the end card.
pub const CX: f32 = 540.0;
pub const CY: f32 = 850.0;

/// Whether the module in this column and row is dark.
pub fn dark(col: usize, row: usize) -> bool {
    GRID[row].as_bytes()[col] == b'#'
}

/// The white tile with the code on it, centered on (`cx`, `cy`) and scaled so the
/// code is `size` pixels wide.
pub fn tile(cx: f32, cy: f32, size: f32) -> Svgr<'static> {
    let k = size / MODULES;
    let pad = size * (TILE - QR_SIZE) / QR_SIZE / 2.0;
    let half = size / 2.0 + pad;
    fframes::svgr!(
        <g>
            <rect x={cx - half} y={cy - half} width={half * 2.0} height={half * 2.0} rx={26.0 * size / QR_SIZE} fill="#ffffff" />
            <g transform={format!("translate({} {}) scale({k})", cx - size / 2.0, cy - size / 2.0)}>{qr()}</g>
        </g>
    )
}
